import {mock} from 'bun:test';
import * as os from 'node:os';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync} from 'node:fs';
import {join} from 'node:path';
const root=mkdtempSync(join(os.tmpdir(),'wx-review-config-')),home=join(root,'home'),project=join(root,'project');mkdirSync(home);mkdirSync(project);
mock.module('node:os',()=>({...os,homedir:()=>home}));
const {loadConfig,resolveDetectedProviderKeys}=await import('../../src/config.ts');
const sa=await import('../../src/agent/subagent_cli.ts');mock.module('../../src/agent/subagent_cli.ts',()=>({...sa,scanLocalAgentClis:()=>[]}));
const {buildConfigApiPayload,renderConfigPageHtml,handleSaveConfigRequest}=await import('../../src/web_config.ts');
const {ContextDatabase}=await import('../../src/db.ts');const {WeChatContextPipeline}=await import('../../src/pipeline.ts');
writeFileSync(join(home,'.env'),'OPENAI_API_KEY=home-fixture\n');process.env.IGNORE_HOME_DOTENV='true';process.env.OPENAI_API_KEY='runtime-fixture';
writeFileSync(join(project,'.env'),'VAULT_ROOT=none\nIGNORE_HOME_DOTENV=true\n');
const detected=resolveDetectedProviderKeys(project).openai?.apiKey;
const cfg=loadConfig(undefined,project),db=new ContextDatabase(cfg.dbPath),p=new WeChatContextPipeline(cfg,db);const data=buildConfigApiPayload(db,p);
const html=renderConfigPageHtml(),uiFn=html.slice(html.indexOf('    function addProviderFromPreset('),html.indexOf('    function createRichModelOption('));
const providers=new Function('appState',`let configuredProviders=[],activeProviderId='',deletedEnvKeys=new Set();const document={getElementById:()=>null};const renderPresetPills=()=>{},renderProvidersList=()=>{},renderModelDropdowns=()=>{},updateRoutingPreview=()=>{},markDirty=()=>{},showToast=()=>{},shortProviderLabel=(n)=>n,isProviderReadyForModels=()=>true;${uiFn};addProviderFromPreset('openai');return configuredProviders;`)(data);
await handleSaveConfigRequest(new Request('http://127.0.0.1/api/config',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({updates:{OPENAI_API_KEY:providers[0].apiKey},deletedKeys:[]})}),db,p);
const uiSavedHome=readFileSync(join(project,'.env'),'utf8').includes('home-fixture');
