writeFileSync(join(project,'.env'),'');delete process.env.OPENAI_API_KEY;delete process.env.IGNORE_HOME_DOTENV;const homeFallback=resolveDetectedProviderKeys(project).openai?.apiKey==='home-fixture';
console.log(JSON.stringify({detected,uiSavedHome,projectWins,homeFallback}));db.db.close();
